cat > /tmp/probe/probe.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test4_executable';
const words = readFileSync('/tmp/probe/words.txt', 'utf8').split(/\s+/).filter(Boolean);
const uniq = [...new Set(words)].filter(w => w !== 'go');

const kw = [];
const notkw = [];
const weird = [];
const CHUNK = 100;
for (let i = 0; i < uniq.length; i += CHUNK) {
  const batch = uniq.slice(i, i + CHUNK);
  const input = batch.join(' , ');
  const out = execFileSync(EXE, ['--a', input], { encoding: 'utf8' });
  const parts = out.split(' , ');
  if (parts.length !== batch.length) { console.error('MISMATCH batch', i, parts.length, batch.length); process.exit(1); }
  for (let j = 0; j < batch.length; j++) {
    const w = batch[j], o = parts[j].trim();
    if (o === w.toUpperCase()) kw.push(w);
    else if (o === w) notkw.push(w);
    else weird.push([w, o]);
  }
}
console.log('KEYWORDS (' + kw.length + '):');
console.log(kw.join(' '));
console.log('\nNOT (' + notkw.length + '):');
console.log(notkw.join(' '));
console.log('\nWEIRD:', JSON.stringify(weird));
writeFileSync('/tmp/probe/kw.json', JSON.stringify({kw, notkw}, null, 0));
EOF
