import { readdirSync, statSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const words = new Set();
function walk(dir, depth) {
  if (depth > 6) return;
  let ents;
  try { ents = readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of ents) {
    const p = join(dir, e.name);
    try {
      if (e.isDirectory()) walk(p, depth + 1);
      else if (e.isFile()) {
        const st = statSync(p);
        if (st.size > 3_000_000) continue;
        if (!/\.(py|txt|md|rst|h|c|cfg|conf|json|html|po|sql)$/.test(e.name) && !/^[A-Z]+$/.test(e.name)) continue;
        const txt = readFileSync(p, 'latin1');
        for (const m of txt.match(/[A-Za-z][A-Za-z0-9_]{0,29}/g) || []) {
          const w = m.toLowerCase();
          if (w.length >= 1 && w.length <= 30) words.add(w);
        }
      }
    } catch {}
  }
}
for (const d of ['/usr/lib/python3.10', '/usr/share/doc', '/usr/share/common-licenses', '/usr/include', '/etc', '/usr/share/perl', '/usr/lib/node_modules']) walk(d, 0);
const arr = [...words].sort();
writeFileSync('/tmp/probe/corpus.txt', arr.join('\n'));
console.log('unique words:', arr.length);
EOF
