import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test4_executable';
const words = readFileSync('/tmp/probe/corpus.txt','utf8').split('\n').filter(Boolean).filter(w => w !== 'go');
const kw = [], weird = [];
const N = 250;
for (let i = 0; i < words.length; i += N) {
  const batch = words.slice(i, i + N);
  const out = execFileSync(EXE, ['--a', batch.join(' , ')], { encoding: 'utf8', maxBuffer: 1<<24 });
  const parts = out.split(' , ');
  if (parts.length !== batch.length) { console.error('MISMATCH at', i); continue; }
  batch.forEach((w, j) => {
    const o = parts[j].trim();
    if (o === w.toUpperCase()) { if (w !== w.toUpperCase()) kw.push(w); }
    else if (o !== w) weird.push([w, o]);
  });
  if ((i / N) % 200 === 0) console.error('progress', i, '/', words.length);
}
writeFileSync('/tmp/probe/bigkw.txt', kw.join('\n'));
writeFileSync('/tmp/probe/weird.json', JSON.stringify(weird));
console.log('KEYWORDS FOUND:', kw.length, 'WEIRD:', weird.length);
EOF
